contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address sp, uint256 v, uint256 w) public {
        require(sp != address(0));
        require(v > 0 && w > 0 && w != v);
        bool first = c.approve(sp, v); if (__ESBMC_reverted()) return;
        uint256 mid = c.allowance(address(this), sp); if (__ESBMC_reverted()) return;
        bool second = c.approve(sp, w); if (__ESBMC_reverted()) return;
        uint256 afterVal = c.allowance(address(this), sp); if (__ESBMC_reverted()) return;
        assert(first && second == false && mid == v && afterVal == v);
    }
    receive() external payable {}
}

